INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1002870-ee370', 'stk-user6860', 'EE 370', 'info', '{"desc": "الكورس الأول في أنظمة الإتصالات ونظرية الإتصالات ، كورس دسم جدا وطويل ينقسم الى قسمين: اتصالات رقمية وغير رقمية ، ثاني أصعب كورس في الكهرب وفيه كمية معلومات لا يغطيها كورس واحد\n\nمستوى الصعوبة: 9 \\10", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-370-communication-engineering/120703/2", "user": "user6860", "ts": 1331167455000, "tid": 120703, "pn": 2}}', 1331167455000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317267-ee370', 'stk-ee-220', 'EE 370', 'info', '{"desc": "الكورس يتكلم عن قسم أنظمة الاتصال ونقل العلومات في تخصص الهندسه الكهربائيه , ينصح بأخذه بعد 207 مباشره لانك راح تستخدم (فورير و لابلاس ) بكثره و مفهوم التردد ( فريكونسي ) .\n\nأول اسبوعين راح تكون مراجعه ل207 (فورير سيريس,فورير ترانسفورم, ديلتا فنكشن , ستيب فنكشن,لينير سستمز … )\nبعد كذا راح تدرسون 7 الى 8 اسابيع عدة طرق لنقل البيانات بين (مُرسل ) و ( مٌستقبل ) , زي مثلاً الإذاعه و الراديو في السياره , وكل طريقة لها مميزاتها عن الطريقه الثانيه و يعتمد على ايش اولوياتك في نظام الإتصال الخاص فيك .\nفي اخر 3 أو 4 اسابيع راح تدرسون نفس اللي فوق لكن لما تكون المعلومات رقميه (01 ) .\n\nالكورس طبعاُ أغلبه ماث , و المفاهيم فيه ماهي صعبه , الدوائر الكهربائيه و تحليلها مافيه أبداً تقريباً معدوم إلى حدِ ما .الكتاب المستخدم للمقرر جيد و تقدر تذاكر منه , لكن عادتاً الشرح و المذاكره تكون من نوت مشهور للماده للدكتور عز الدين زرقوين , تقريباً نسخ للكتاب .\n\nالأختبارات و الفاينلات سهله جداً , الدكاتره مسهلين الماده هذي و الأسئله ماتطلع من اللي في النوت او اسئلة الواجب (على الاقل في الترم اللي اخذت الماده فيه ) .\n\nالاب,سهل إلى متوسط , العمل في المعمل عباره عن تشيك اسلاك بسيط و رؤية النتائج على برنامج خاص في الكمبيوتر ( قريب إلى طريقة لاب 360) , مافيه بري لاب , لكن فيه ريبورت و يعتمد اعتماد كامل على (الماتلاب ) حتى اول تجربه شرح للماتلاب وطريقة استخدامه للاب ال 370 .\n\nالهوموركس من الكتاب وفيه مانيوال سلوشن , و فيه بروجكت وكل ترم يتكرر , اللي هو تصميم دائره كهربائيه عباره عن إذاعة fm , بحيث بنهاية البروجكت تتكلم بالمايك اللي في السيركت و تسمع صوتك في الراديو على فركونسي معين . البروجكت سهل مجرد تشبك السيركت زي ماهو معطيك في الصوره .\n\nكورس بالمجمل اساسي ومهم لاي شخص مهتم بمجال الإتصالات .\nبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-370-communication-engineering/120703/3", "user": "EE-220", "ts": 1389182298000, "tid": 120703, "pn": 3}}', 1389182298000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1491742-ee370', 'stk-mr.a1', 'EE 370', 'info', '{"desc": "Term 172 with Wesam Mesbah\n\nجودة المقرر بشكل عام\nممتاز. يتحدث عن المفاهيم الاساسية في هندسة الاتصالات ، بشكل أساسي عن أساليب تعديل الاشارات وتجيهزها للنقل ، أو ما يسمى بالـ Modulation.\n\nالمواضيع التي يغطيها المقرر\nأول جزئية من المنهج (اجزاء من تشابترز ١-٣) بتكون مراجعة للنقاط المهمة من EE 207 ، ونصيحة إفهم EE 207 مضبوط لأنك بتحتاجها هنا ، وحاول ما تفصلها كثير عن EE 370.\nبعد كذا تدخل على المنهج الاساسي:\nCh4: Amplitude (Linear) Modulation\nCh5: Angle (Phase or Frequency) Modulation\nCh6: Sampling Theorem and Digital Modulation\nCh7: Digital Communication\nتشابترز ٤-٥ تتكلم عن الـ Analog ، بينما تشابترز ٦-٧ تتكلم عن الـ Digital.\n\nالكتاب المستخدم للمقرر\nكويس. أمثلته جيدة وتشرح المفاهيم بشكل جيد ، بالإضافة إلى عدد جيد من الاسئلة نهاية كل تشابتر. ما اعجبني فيه إنه يطيل في الشرح بشكل ما له داعي.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nممتازة. يعيب أسئلة الاختبارات أنهم يتشعبون في الـ signal processing إذا يبون يطيحون الآفرج. 😆\nأيضا مفاهيم المادة كثيرة جدا ومتشعبة ، لذلك لازم تذاكر لها بشكل يومي.\n\nمدى فائدته في الناحية التطبيقية\nالمادة تعتبر مدخل لهندسة الاتصالات ، بالإضافة إلى دخولها في العديد من التطبيقات ، وراح تناقش بعضها في المادة مثل الـ Stereophonic System اللي راح تشوفها في المادة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-370-communication-engineering/120703/5", "user": "Mr.A1", "ts": 1525332298000, "tid": 120703, "pn": 5}}', 1525332298000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509458-ee370', 'stk-abdullah2015', 'EE 370', 'info', '{"desc": "EE370\n\nأخذت المادة مع الدكتور علي مقيبل في ترم 181.\n\nجودة المقرر بشكل عام:\nممتازة.\n\nالمواضيع التي يغطيها المقرر :\n\nبشكل أساسي المادة تنقسم إلى أربعة أقسام رئيسية:\n\n- القسم الأول: مراجعة لما أخذته في مادة EE207 والتي تعتبر أساس مهم لهندسة الاتصالات.\n\n- القسم الثاني: Amplitude Modulation (أو ما يعرف اختصارًا ب AM) وهو معني بعملية إرسال البيانات حينما تكون الرسالة مضمنة في الAmplitude الخاص بالحامل (Carrier).\n\n- القسم الثالث: Angle Modulation وهو معني بعملية إرسال البيانات حينما تكون الرسالة مضمنة في الزاوية الخاصة بالحامل (Carrier).\n\nوللتوضيح، الحامل أو Carrier عبارة عن Sinusoidal wave تقوم بحمل الرسالة، والModulation هي عملية تضمين أو تحميل الرسالة في هذا الحامل أو Carrier. لما نضمن الرسالة في الAmplitude لهذه الWave، نسمي هذي العملية Amplitude Modulation ولما نقوم بتضمين الرسالة في الAngle لهذه الWave نسمي هذي العملية Angle Modulation.\n\nالAngle Modulation ينقسم إلى نوعين، الأول هو Phase Modulation وهو عندما يتم تضمين الرسالة في الPhase الخاص بالCarrier والثاني هو Frequency Modulation (أو ما يعرف اختصارًا ب FM) وهو عندما يتم تضمين الرسالة في الFrequency الخاص بالCarrier.\n\nملاحظة: القسم الثاني والثالث عبارة عن Analog Communications.\n\n- القسم الرابع: Digital Communications وهو معني بعملية إرسال البيانات عندما تكون البيانات المرسلة رقمية ( 0 و 1) وليست تناظرية (Analog).\n\nطبعًا معظم أنظمة الاتصالات الحديثة اللي نشوفها عبارة عن Digital Communications Systems.\n\nالكتاب المستخدم للمقرر:\nhttps://s1.gulfupload.com/i/00091/39fpbjabgbbh.png\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nممتازة، ولكن كالعادة، تحتاج تشوف أولد إقزام عشان تحضر لاختبارات المادة. الكتاب وأسئلته، في نظري، ما يكفون.\n\nمدى فائدته في الناحية التطبيقية:\n\nالكورس يعتبر مقدمة لمجال الاتصالات، فمهم جدًا إنك تعرف أساسيات الاتصالات إذا كنت ناوي تكمل في هذا المجال. إذا كنت مهتم في الموضوع فأنصح بأخذ كورسات متقدمة من المستوى الرابع في هذا المجال وشخصيًا أنصح ب EE400 وEE419 لأن فيها مواضيع عملية تطبيقية في هندسة الاتصالات.\n\nملاحظات:\n\n- المقرر دسم جدًا وكمية المعلومات اللي فيه كثيرة على كورس واحد. المقرر ما هو صعب، والمفاهيم اللي فيه سهلة الهضم لكن مشكلته مع كمية المعلومات الكبيرة. فبالتالي تحتاج إلى مراجعة محترمة حتى تقدر تجيب قريد كويس.\n\n- هناك خطأ شائع وهو حصر الاتصالات في شبكات الكمبيوتر والإنترنت والهاتف وما شاكل، والواقع أن الاتصالات علم كبير ويشمل كثير من الأشياء.\nالتقنيات الحديثة مثل Internet of Things هذي كلها اتصالات. تقدر تفكر بحساسات وأنظمة تحكم متصلة ببعض عشان توصل الفكرة.\n\nبالتوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-370-communication-engineering/120703/6", "user": "Abdullah2015", "ts": 1557260339000, "tid": 120703, "pn": 6}}', 1557260339000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527366-ee370', 'stk-user11634', 'EE 370', 'info', '{"desc": "Term 201\nجودة المقرر:\nيعتبر المقرر مقدمة في هندسة الاتصالات، ويزود الطالب بأساسيات هذا الفرع من الهندسة الكهربائية، ويعنى المقرر بشكل أساسي بدراسة عمليتي الـ Modulation (تغيير تردد الإشارة إلى تردد أعلى) لدى المرسل، والـ Demodulation (إرجاع الإشارة إلى ترددها الأصلي) لدى المستقبل، وهاتان العمليتان مهمة لتجنب تداخل الإشارات؛ لأن كل إشارة يتم تغيير ترددها إلى تردد عالي مختلف عن تردد الإشارات الأخرى، وكذلك إذا كان تردد الإشارة منخفض فالأمر يتطلب هوائيات (Antennas) عملاقة لاستقبال الإشارة؛ لذا لا بد من رفع التردد لتقليل حجم الهوائي، وهناك أسباب أخرى أيضا للـ Modulation، ولكن هذه أكثرها وضوحا.\nالمواضيع التي يغطيها المقر:\nيمكن تقسيم المقرر إلى ثلاثة أقسام:\n1- Ch1 - Ch3: مراجعة لـ EE207، ومن أهم المفاهيم هي Fourier Transform وخصائصه، وكذلك مقدمة عن أنظمة الاتصالات ومكوناتها.\n2- Ch4 & Ch5: يتناول هاذان الفصل عمليتي الـ Modulation والـDemodulation للإشارات من نوع Analog Signals، فالفصل الرابع يناقش Amplitude Modulation أو اختصار AM، وأما الفصل الرابع فيتناول Frequency Modulation أو FM و Phase Modulation أو PM.\n3- Ch6 & Ch7: يتناقش هاذان الفصلين الإشارات الرقمية أو الـ Digital Signals، فالفصل السادس يناقش عملية تحويل الـ Analog Signals إلى Digital Signals من خلال الـ Sampling ثم الـ Quantization، وأما الفصل السابع فيناقش أنواع الـLine codes المستخدمة لنقل الإشارات الرقمية، وكذلك أنواع الـ Modulation والـDemodulation المستخدمة معها.\nالكتاب المستخدم للمقرر:\nB. P. Lathi and Z. Ding, Modern Digital & Analog Communication Systems, Oxford University\nPress, 4rd Ed., 2010\nالأسئلة والأمثلة المستخدمة في المقرر:\nأمثلة الكتاب جيدة وتعتبر تحضير جيد، وبالتأكيد جنبا إلى جنب مع الأولد إقزام، كذلك هناك أسئلة الواجب من الكتاب.\nمدى فائدته في الناحية التطبيقية:\nالمادة تعتبر اللبنة الأولى في مجال هندسة الاتصالات، وكل من يريد أن يكمل في هذا المجال عليه أن يلم بالمفاهيم الواردة فيها، وأن يتأكد من فهمها بشكل عميق وتطبيقي.\nإضافات:\n1- من المهم مراجعة Fourier Transform وخصائصه، لأنها مهمة جدا في هذه المادة خاصة في الـ Analog Signals.\n2- قناة الدكتور علي مقيبل في اليوتيوب تعتبر مصدر مذاكرة جيد.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-370-communication-engineering/120703/9", "user": "user11634", "ts": 1609253589000, "tid": 120703, "pn": 9}}', 1609253589000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11634-ee370', 'stk-user11634', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98377", "n": "Dr. S. Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201-EE370\nهذا الفصل كان استثنائيا؛ لأنه كان كاملا عن بعد بسبب جائحة كورونا.\nالتحضير :\nالمحاضرات كانت عن طريق مايكروسوفت تيمز، والتحضير كان عشوائي أوقات في بداية المحاضرة وأوقات آخرها.\nطريقة الشرح :\nالدكتور سعد لديه مشكلة في إيصال المعلومة للطالب، فهو يقرأ من النوتات أوالكتاب، ولا يكتب أي شيء أثناء المحاضرة، لذلك تشعر بالضياع في المحاضرة، وتقريبا من المستحيل أن تفهم منه شيء أثناء المحاضرة، إلا أذا كنت محضرا من قبل.\nالكويزات :\nأعطانا 4 كويزات وواحد منها كان اختياري، وكويزاته من سهلة إلى متوسطة، وكلها Written، بعدها نصور الحل بالجوال ونرفعه على البلاك بورد.\nأون لاين تيست: عددها 2 وكانت Written، ولكل سكشن اختبار خاص به.\nاختبار منتصف الفصل: لكل سكشن اختبار، وكان اختيارات وTrue &False وWritten.\nالفاينلات : موحد، وكان اختيارات وTrue &False وWritten.\nالقريد النهائي: +C\nالصوت:واضح، ولغته الإنجليزية ولكنته ممتازتان.\nإضافات : الدكتور سعد متعاون في التصحيح، لذلك سيستفيد طلابه من هذا في الـWritten Part من المياجر والفاينل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527454-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-ahmadi/98377/32", "user": "user11634", "ts": 1609509545000, "tid": 98377, "pn": 32}}, {"id": "stk-dr-f98521", "n": "Dr. R. Al-Ohali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201-EE370-LAB\nهذا الفصل كان استثنائي؛ لأنه كان عن بعد بسبب جائحة كورونا.\nالتحضير :\nاللاب كان عن طريق برنامج زوم، وكان الدكتور يحضر في بداية اللاب في كثير من الأحيان، ومرات ما يحضر، ولكن يقول افتحوا الكاميرات.\nطريقة الشرح :\nشرح الدكتور ممتاز، ويوضح الهدف من التجربة ويربطها بالجزء النظري بشكل ممتاز، وبما أن هذا الفصل كان عن بعد، فاضطررنا لاستخدام برامج محاكاة بديلا عن الأجهزة في اللاب، واسمه tutorTims.\nالكويزات :\nكان هناك 4 كويزات، وكانت عن الماتلاب والجزء النظري في اللاب مانيوال، وكلها كانت عن طريق البلاك بورد.\nالفاينلات :الفاينل كان حوالي 30 سؤال وكانت شبيه جدا بأسئلة الكويزات، وكان هناك اختبار لفظي واختبار باستخدام برنامج المحاكاة tutorTims.\nالقريد النهائي:+A\nالصوت: واضح\nإضافات :\n1- الدكتور راكان حريص على مصلحة الطالب، ويوجه الطلاب أثناء اللاب على تحسين مستواهم، والاستفادة من أخطائهم في التجارب السابقة.\n2- الطالب الحريص الذي يسجل ملاحظات مع الدكتور خاصة في أول اللابات، سيحصل على درجة عالية مع الدكتور، ولاحظت بأن مشكلة أغلب الطلاب كانت في عدم فهمهم لأساسيات الماتلاب والتجارب الأولى في اللاب، لذلك عانوا طوال الفصل، فإذا استطعت أن تتجنب هذه المشكلة، وأنجرت تقارير الماتلاب أول بأول بفهم، بإذن الله سيكون حالك في اللاب ممتاز وستحصل على درجة عالية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527462-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-al-ohali/98521/10", "user": "user11634", "ts": 1609520021000, "tid": 98521, "pn": 10}}]}', 1609509545000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee370', 'stk-mr.a1', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f167060", "n": "Dr. Abdullah Al-Battal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 172 EE 370 (LAB)\n\nالتحضير :\nأول لاب بيطلب منكم تكتبون اسماؤكم بالعربي على ورقة ، وبيحضر منها بداية اللاب. بعض المرات ما يحضّر.\n\nطريقة الشرح :\nيستخدم السبورة ويكتب توضيحات عليها ، ويشرح بشكل شفوي. بعض الاحيان يستخدم البروجيكتر لو احتاج يعرض شيء. بعض التجارب تكون فيها شغلة بسيطة بس ، يسويها توتوريال قدام الطلاب ويشرحها لهم وخلاص (سواها مرة أو مرتين تقريبا). في المجمل شرحه كويس ، ومهما سألته في الشرح بيجاوبك.\n\nالكويزات :\nأخذنا ٤ كويزات. مستواها متوسط إلى سهل. للأمانة حسيت الكويزات غريبة اشوي. أول كويز كان عبارة عن Theory بالكامل. بعدين ابتدأ يدخل الماتلاب والاشياء العملية في الكويزات اللي بعده. الغريب فيها إنك ما تتوقع كيف ممكن تجيك الاسئلة ، وممكن تتفاجأ فيها 😅.\n\nالمياجر:\n-\n\nالفاينلات :\nكان كله تحريري ، ما فيه جزء عملي. مستوى الفاينل وسط. كانت الاسئلة خليط ما بين الاختيارات والريتن ، وفيها اسئلة نظرية ، أسئلة ماتلاب ، وأسئلة عن الاشياء اللي سويتها خلال التجارب بعد.\n\nالقريد النهائي:\nA\n\nالصوت:\nممتاز وواضح. لكنته الانجليزية ممتازة.\n\nإضافات :\n١. حبيب ومتعاون درجة أولى مع الطلاب. متى ما احتجت تقدر تروح له المكتب ولا راح يقصر معك ، وغير كذا اكثر من مرة طلبوه الطلاب يؤخر تسليم الريبورت وما قال شيء.\n٢. يساعدك في التجربة لو صارت عندك مشكلة في شغلة محددة ، ويشرح لك وين الخطأ.\n٣. أحد النقاط السلبية فيه إنه أحيانا يذكر شغلات في اللاب -تكون مثلا عن المطلوب في الريبورت- لكنه ما يحط إعلان على البلاك بورد ، فاللي ما ينتبه لهالنقطة ممكن ما يدري وش يحط ويتورط. لذلك انتبه معه في اللاب.\n٤. شغلة مرتبطة باللي قبلها ، وهي التركيز. لو ذكر شغلة محددة في الشرح ونبه عليها ورجعت تسأله عنها يمكن يزبد لك 😆. أيضا لو شغلة في المانيوال أو في الـ Data Sheet حق قطعة ورحت تسأله عنها بيقول لك رح إقرأ.\n٥. ما قصّر معنا في الدرجات. الآفرج كان طايح وزودنا بشيء محترم مع النورملايزيشن.\n\nكل اللي أقدر أقوله ، الله يعطيه العافية…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492042-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-battal/167060/8", "user": "Mr.A1", "ts": 1525886389000, "tid": 167060, "pn": 8}}, {"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 172 EE 370\n\nالتحضير :\nنهاية المحاضرة. يعطيك ١٠-١٥ دقيقة ، بعدها يبدأ يسجل أي واحد يدخل تأخير. ما يسمح إنك تحضر مع شعبة ثانية.\nأعتقد حذف غياب لكل واحد لأنه عطاني فل في الحضور مع إن عندي غياب.\n\nطريقة الشرح :\nعلى السبورة ، واحيانا يستخدم نوت د. زرقوين مع بعض الاضافات الشخصية عليها. تركيزه في الشرح على المفاهيم (الكونسبت) ونادرا يحل مسائل بالارقام. بالنسبة لي اشوف شرحه واضح ويعرف كيف يوصل المعلومة بشكل ممتاز.\n\nالكويزات :\nأخذنا ٦ كويزات تقريبا ، ما أدري كيف حسبتها في الكلاس وورك. غالبا كويزاته تجي مسألة ، وبعدها كم سؤال كونسبت ريتن ، يعني تحتاج تكون فاهم وتعرف كيف تعبر بشكل صحيح.\n\nالمياجر:\nكومون مع الدكتور الثاني ، تقريبا نص الاسئلة تجي كونسبت ما بين صح وخطأ واختيارات ، بالاضافة لكم مسألة. مستوى المياجر وسط وتحتاج مذاكرة مضبوطة وفهم.\n\nالفاينلات :\nنفس المياجر.\n\nالقريد النهائي:\n+B\n\nالصوت:\nكويس. أغلب الشرح بالعربي (لكنة مصرية) ، مع دخول بعض المصطلحات الانجليزية.\n\nإضافات :\n١. احد ابرز سلبيات الدكتور أنه يرفض يجيب أي اختبارات معه أو يرفع حلول. يعني مثلا ، حليت الهومورك ولقيت القريدر خاصم عليك ؟ تروح له المكتب وتشوف السولوشن عنده. مثلا ، خلصتوا كويز او ميجر ونزل لك الدرجة على البلاك بورد ؟ رح له المكتب وشف السولوشن عنده هناك.\n٢. مرن في موضوع تسليم الواجبات ، وما تحتاج تسلمه في الكلاس. نفس اليوم اللي يكون فيه تسليم الهومورك ، عندك الى الساعة ٣ العصر تسلم الهومورك على باب المكتب.\n٣. سريع اشوي في الشرح ، ويلغي محاضرات كثير خلال الترم.\n\nفي المجمل الدكتور جيد جدا ، وحبيب وتعامله كويس مع الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492358-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/29", "user": "Mr.A1", "ts": 1526307363000, "tid": 98387, "pn": 29}}]}', 1525886389000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ee_specialist-ee370', 'stk-ee_specialist', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 181 EE 370\nنفس كلام Mr.A\nبس عندي بعض الإضافات:\nلم يلغي حصص كثيره في الترم، مجرد أخر كلاسين في الترم\nمن ناحية التصحيح:\nأشوفة عادل جدا.\nالفانيل كان أصعب شوي من المياجر\nالقريد النهائي:\n+B بس لو يترك حركت عدم رفع حلول الاختبارات وكوزات والهومورك أعطيه A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504139-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/30", "user": "EE_Specialist", "ts": 1545889324000, "tid": 98387, "pn": 30}}, {"id": "stk-dr-f167060", "n": "Dr. Abdullah Al-Battal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Term 172 EE 370 (LAB\nالتحضير :\nبداية اللاب (دائما).\nطريقة الشرح :\nممتاز\nالكويزات :\nالصعوبة تكمن في عدم قدرة الطالب توقع الاسألة\nالكوز الاول:Theory\nالكوز الثاني:Matlab\nالكوز الثالث:Block and Module Diagram\nالفاينيل:\nكان كل الانواع الثلاثة.\nالقريد:\nA\nإضافات:\n-متعاون في مواعيد التسليم.\n- أحد النقاط السلبية فيه إنه أحيانا يذكر شغلات في اللاب -تكون مثلا عن المطلوب في الريبورت- لكنه ما يحط إعلان على البلاك بورد ، فاللي ما ينتبه لهالنقطة ممكن ما يدري وش يحط ويتورط. لذلك انتبه معه في اللاب.(Mr.A)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504141-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-battal/167060/9", "user": "EE_Specialist", "ts": 1545891979000, "tid": 167060, "pn": 9}}]}', 1545889324000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-1zezo1-ee370', 'stk-1zezo1', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98518", "n": "Dr. Ali Muqaibel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 370 - TERM 151\n\nالتحضير : كل يوم بداية الكلاس ينادي بالاسماء\nطريقة الشرح : سلايدات ويستخدم السبورة للتوضيح…شرحه مرررررة ممتاز\nالكويزات : كل أسبوعين تقريبا أو كل اسبوع…متوسطة إلى سهلة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح جدا…لغته جيدة…يشرح بالعربي في بعض الأحيان\nإضافات : دكتور ما شاء الله عليه حبيب وأخلاقه عالية جدا 🌹 كلاسه ممتع…يهتم بالطلاب…اذا حس جو الكلاس بدأ يصير ممل يوقف شرح لفترة بسيطة\nيقول فيها معلومات أو يغير الجو بنكتة…يذكر تطبيقات للكلام اللي ندرسه مو مثل بعض الدكاترة يسرد الكتاب سرد…\nمتعاون جدا في office Hour", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440014-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-muqaibel/98518/9", "user": "1zezo1", "ts": 1453337516000, "tid": 98518, "pn": 9}}, {"id": "stk-dr-f152994", "n": "Dr. Hamood Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 370 LAB - TERM 151\n\nالتحضير : يمر باللابتوب كل لاب\nطريقة الشرح : يشرح التجربة بشكل مفصل\nالكويزات : متوسطة\nالفاينلات : كان طويل وكله written قال بيجيب ماتلاب لكن خمنا في هذي الهرجة\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : حاول تكتب معاه بعض الكلام اللي يقوله وهو يشرح لأنه يكون إجابة لبعض أسئلة الريبورت\nماهو متساهل جدا ولا ومتشدد جدا في التصحيح وهذا شي كويس عشان يرفع الطلاب بعد ما يرفع الأفرج", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440018-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hamood-khan/152994/5", "user": "1zezo1", "ts": 1453339957000, "tid": 152994, "pn": 5}}]}', 1453337516000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-ee370', 'stk-magbool', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98518", "n": "Dr. Ali Muqaibel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 - Term 151\n\nبنود التقييم :\n\nالتحضير :\nفي بداية الكلاس تماما ، يعني إذا حضرت بعد 5 دقايق غالبا حتتسجل Late.\n\nطريقة الشرح :\nمن أفضل الدكاترة في الشرح ، شرح واضح وبسيط للمنهج، يشرح عربي وانقليزي ، وفيه ميزة إنه يوسع مداركك بخصوص المادة اللي تدرسها ويربطها بتطبيقات خارجية في الحياة العملية ، أكثر من مرة يشغل لنا فيديو أو يناقش موضوع متعلق بالاتصالات ونظرياتها خارج إطار المنهج.\n\nالكويزات :\nسهلة وغالبا ما تكون متكررة من الأولد كويزز حقته بتغيير الأرقام ، والميزة إنه موقعه الشخصي مليان كويزات قديمة.\n\nالمياجر:\nمتوسطة مائلة للصعوبة ، لكن ميزة الدكتور لمن يشوف الاختبار صعب ع الطلاب يدف بالتصحيح.\n\nالفاينلات :\nنفس وضع المياجر.\n\nالقريد النهائي:\nA+\n\nالصوت:\nممتاز وواضح.\n\nإضافات :\nدكتور حبيب ومتعاون وروحه شبابية ، يحفظ الأسماء من بداية الفصل ويصير يعرفك شخصيا، يحب يغير جو الكلاس كثير، قبل المياجر والفاينال يخصص كلاس للمراجعة ويحل فيه أولد أقزام ، يخليك انتا تستخلص المعلومة من خلال طرح أسئلة عن الموضوع .\n\nمن أفضل دكاترة القسم شرحاً وتعاملاً .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440149-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-muqaibel/98518/10", "user": "magbool", "ts": 1453463600000, "tid": 98518, "pn": 10}}]}', 1453463600000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-ee370', 'stk-abdullah2015', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98518", "n": "Dr. Ali Muqaibel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور علي مقيبل\n\nأخذت معاه EE370 في ترم 181\n\nالتحضير :\nيحضر على بداية الكلاس بالضبط.\n\nطريقة الشرح :\nبداية الكلاس يكتب الObjectives على السبورة ومن ثم يقوم بالشرح من السلايدات، ويستخدم السبورة لما يكون فيه حل معادلات وغيره.\nشرحه واضح ومفهوم والدكتور جدًا متمكن من المادة.\n\nالكويزات :\nعادية الصعوبة، إذا كنت مذاكر تقدر تجيب فل مارك.\n\nالمياجر:\nكومون، وفي تصحيحه للمياجر كان ماشي على السلوشن كي، يعني يعطيك حقك من غير زيادة أو نقصان.\n\nالفاينلات :\nكومون.\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح.\n\nإضافات :\nالدكتور من أفضل الدكاترة المتخصصين في الاتصالات في القسم، أنصح به.\n\nبالتوفيق …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507102-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-muqaibel/98518/14", "user": "Abdullah2015", "ts": 1552334215000, "tid": 98518, "pn": 14}}]}', 1552334215000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee370', 'stk-user6130', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله \" سمستر 113 \" ee 370 :\n\nالشرح : يشرح من نوت هو كاتبها و شرحه ممتاز إذا ركزت معه لأنه يشرح بسرعة و ما ألومه لأنه صيفي و الكورس طويل بس في السمستر العادي أتوقع شرحه بيكون أفضل.\n\nالكويزات : عطانا 7 كويزات و أخذ أحسن 4 و كانت كلها سهلة ما عدا واحد كان وسط .\n\nالمياجر : سهلة جداً بس لازم تذاكر كل شي في نوته كل شي حتى البلوك ديجرام.\n\nالفاينل : سهل و جاب أغلبه من الأولد أقزام لانه سمستر صيفي و ما في وقت يجيب أسئلة جديدة.\n\n* إضافات :\n- زي ما قالوا الإخوان هو يُعتبر من أفضل الدكاترة في كورسات الكوميونكيشن زي 207 و 315 و 370\nو إذا شفته منزل واحد منها نزل عنده و ما راح تندم إن شاء الله.\n\n- يدف دف محترم في القريدات إذا كان الكورس ما هو كومن.\n\nالقريد النهائي : A .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1076079-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/10", "user": "user6130", "ts": 1344183257000, "tid": 98519, "pn": 10}}]}', 1344183257000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir111-ee370', 'stk-muntathir111', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 Term 201\nالترم طبعا اونلاين\n\nالتحضير : ماحد يعرف شي بس على الاغلب كان ياخذ التحضير من البلاكبورد\nطريقة الشرح : يشرح ويكتب باستخدام الماوس بالنسبة لي كليا ماصلح لي بحكم ان الجودة سيئة. ما انكر انه في ناس تأقلمو على الخط ومشت امورهم ولكن هالشي على الطالب. بالنسبة لي المادة خليتها سلف ستدي ومقاطع الدكتور مقيبل\nالكويزات : سهلة وتختبر الفهم بشكل اساسي ورتن\nالمياجر:\nالفاينلات :\nالقريد النهائي: C+\nالصوت: واضح\nإضافات :\n\nزرقوين يعيبه عدة اشياء\nشرحه سيئ اونلاين\nباختصار يكتب ويحل بماوس وهالشي مايصلح لي كليا طبعا شرا ايباد بس ما امداه يتعلم عليه فممكن الي ينزل معاه السمستر الجاي يتضبط\nثانيا يستعمل البلاكبورد للكلاسات فمايمديك تسجل كلاساته\nثالثا والاهم ماعطانا لا درجات الكلاس ورك ولا درجات الفاينل\nبس شفنا القريد النهائي بالبورتال وماكان حسب المتوقع\nالدكتور كان دايم يقولنا بشرو بالدرجات من بداية السمستر وكلكم B وفوق وكذا بس بالنهاية كانت الدرجات مخيبه للآمال\n\nالحين مميزاته\nالدكتور طيب ومسهل ام ام المادة\nاختباراته سهله وبيسك ويحدد لك للفاينل وش بيجي ووش مب يجي\nوالبروجكت حقه كان عبارة عن تنسخ الكود من الكتاب وتسوي سيموليشن بس والاغلب فل\n\nايضا كاميرات اللابتوب طلب بالفاينل والميد الامامية بس ( يعتبرها البعض ميزة والبعض سلبية )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527515-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/20", "user": "Muntathir111", "ts": 1609670840000, "tid": 98519, "pn": 20}}]}', 1609670840000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedgs-ee370', 'stk-mohammedgs', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98519", "n": "Dr. Azzedine Zerguine", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370-T201 (Online)\n\nالتحضير: ما كان يحضر بشكل مباشر بس يقول إنه ياخذ التحضير عن طريق البلاكبورد بما إنه كان يستعمل البلاكبورد في الشرح وأحيانًا كان ينادي أسماء عشوائية يسألهم لو فهموا ولا لا.\nطريقة الشرح: طبعًا زي ما قلت يستعمل البلاكبورد كمنصة شرح ويستعمل الماوس للكتابة. يشرح من نوتته وأحيانًا يفتحها ويبدا يكتب عليها. شرحه ممتاز جدًا بس يبيلك تتعود على خطه بالماوس وطريقة شرحه وبيصير الوضع تمام.\nمن الأشياء اللي حابها فيه واللي فاقدها في دكاترة كثير هي حل المسائل، الدكتور يحل كمية كبيرة من المسائل لدرجة إنه ياخذ كم كلاس يشرح كونسبت بعدها كلاس كلاسين يكونون مخصوصين لحل المسائل وحل الهوموورك فلو تركز معه بتعرف تحل زين.\nالكويزات: سهلة إلى متوسطة أغلبها نفس أفكار الهومووركات.\nالمياجر: كومون وتصحيح بطللللل.\nالفاينلات: كومون.\nالقريد النهائي: A++++\nالصوت: واضح ويتكلم عربي وانجليزي.\nإضافات:\n١- الكلاس معه مب رسمي أبد وينكت ويضحك وعليه فصلات حلوة، ما تحس بالكلاس معه أبد.\n٢- زي ما قلت فوق تصحيح الدكتور بطل جدًا أغلب الناس جاهم في الميد أعلى من اللي توقعوه بكثييير.\n٣- الدكتور يعطي هيلب سيشنز يحل فيها مسائل زيادة ممتازة لا تفوتها.\n٤- الدكتور قبل الميد سوا كلاس مراجعة ويلمح أحيانًا للأشياء المهمة لا تفوت كلاس المراجعة نهائيًا وركز معه وركز على الحاجات اللي يقول عنها مهمة.\n٥- لا تفوت الدكتور لو لقيته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527536-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azzedine-zerguine/98519/21", "user": "MohammedGS", "ts": 1609715146000, "tid": 98519, "pn": 21}}, {"id": "stk-dr-f152989", "n": "Dr. Motaz Al-Farraj", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 LAB-T201 (Online)\n\nالتحضير: زي كل لاب من بعد ٥ دقايق يبدا ينحط ليت ويخصم على كل ٥ دقايق زيادة والدكتور متشدد من ناحية التحضير، أحيانًا يسأل سؤال لواحد ولو ما رد يغيبه فانتبه وخلك مركز معه.\nطريقة الشرح: ممكن هذا أكثر شي يميز الدكتور، شرحه بطل جدًا جدًا وأحيانًا يغنيك عن شرح الليكتشر! يستخدم تيمز ويشرح بالآيباد بطريقة مرتبة وممتازة جدًا ويوصل المعلومة بشكل ممتاز.\nالكويزات: سهلة إلى متوسطة تجي من شرحه فخلك مركز وقت الشرح.\nالمياجر: لا يوجد (لاب).\nالفاينل: متوسط وشبيه بالكويزات.\nالقريد النهائي: A+\nالصوت: واضح وأغلب كلامه انجليزي بس أحيانًا يتكلم عربي بعد.\nإضافات:\n١- الدكتور شديد جدًا جدًا من ناحية الغش والنقش فلو كنت من النوع اللي ينقل ريبورتات أو بوست لابات لا تنزل معه عشانك بتاخذ DN.\n٢- الدكتور شباب ومتفهم للطلاب بشكل كبير، صح إنه شديد ونظامي من نواحي عدة بس إنه يظل محترم وحبيب ويهتم بفهم الطالب.\n٣- يرد في أي وقت على التيمز وينتقد اللي يخطون في الكويزات أو فيه حاجة ما فهموها ولا يرسلون له تيمز، لا تتردد تسأله لو كان في شي ما فهمته بيحرص إنك تطلع فاهم.\n٤- يعيب الدكتور إنه أحيانًا يطول مرة بالشرح (أحيانًا ياخذ ساعتين كاملة) فتنحشر أحيانًا بالتجربة وتحاول تعجلها.\n٥- لو لقيته في كورس ثاني بنزل عنده بدون تردد، ليته يدرس ليكتشر في المستقبل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527538-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/motaz-al-farraj/152989/4", "user": "MohammedGS", "ts": 1609716930000, "tid": 152989, "pn": 4}}]}', 1609715146000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hzx_300-ee370', 'stk-hzx_300', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98521", "n": "Dr. R. Al-Ohali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يدرس لاب ee370 غالبا\nطريقته يحضر من البداية ويأخذ التأخير\nراح يساعدكم كثير في الريبوت ووالكود حق الماتلاب لانه فاهم عدل للماتلاب\nعنده 4 الى 5 كوزات اذا راجعت وكنت فاهم راح تحلهم\nالفاينل عليه 9 درجات اتوقع وكله اختياري, على قد فهمك راح تجاوب(اثناء الشرح يقول هذا راح اسألكم عنه في الفاينل وكذا على طول سجله لانه راح يجي 10000000000000%)\nلا تحاول تغش عنده ابدا لانه يكشف براحه\nيحب يسمع من الطلاب ويأخذ اقتراحاتهم\nفي النهايه راح تطلع فاهم لاب ee370 صح اذا كنت متابع معاه اول بأول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p741244-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-al-ohali/98521/3", "user": "hzx_300", "ts": 1291579955000, "tid": 98521, "pn": 3}}]}', 1291579955000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muath.12-ee370', 'stk-muath.12', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f98521", "n": "Dr. R. Al-Ohali", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه لاب EE370 الفصل 203 أون لاين\n\nالتحضير :\nمرات ومرات\n\nطريقة الشرح :\nشرح الدكتور كويس، يشرح ببورد أبيض وغالبًا شرحه يكون عن الماتلاب ويصور لك البورد ويرسلها بالايميل لك كمرجع راح يفيدك أثناء كتابة الريبورت\n\nالكويزات :\nعطانا 3 كويزات وكويزاته كانت صعبة وافرجها مرة نازل، بس كان الكلاس اللي بعده يمشي على اسئلة كل كويز ويحلها.\n\nالفاينلات :\nالفاينل كان قسمين قسم عن الثيري وهذا كان أغلبه جاي من الكويزات فإذا كنت مركز معه في حل الكويزات غالبًا راح تحل 80% من الاختبار، القسم الثاني هو اورال اقزام وصراحة كان الوضع تحجير شويتين كان يقعد مع كل طالب 10 دقايق تقريبًا وما يبقى سؤال ما يسأله واسئلته تكون يا عن كونسبت أو يطلب منك توريه طريقة تشبيك شي معينة ب TutorTims.\n\nالقريد النهائي:\nB+ بسبب صعوبة اختباراته.\n\nالصوت:\nواضح.\n\nإضافات:\nالدكتور حبيب جدًا ومزوح مع الطلاب ويجاوب على أسئلة الطلاب ومتساعد معهم لكن يعيبه أمرين الأول هو صعوبة اختباراته والأمر الثاني هو تصحيح الريبورت، يعني عادي يعطيك نص درجة الريبورت أو حولها وغالبًا على أشياء تافهة وتشوفه ينقص على نفس النقطة كذا مرة يعني مثلًا نسيت العنوان لل graph راح يخصم عليه واذا في مثلًا أكثر من graph راح يخصم عليهم كلهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531205-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-al-ohali/98521/11", "user": "Muath.12", "ts": 1628778253000, "tid": 98521, "pn": 11}}]}', 1628778253000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11794-ee370', 'stk-user11794', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f115363", "n": "Dr. Salam Adel Zummo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 - Term 222\n\nالتحضير : بشكل عشوائي خلال الكلاس يطلب منك انك ترسله رساله في تيمز ويحضرك على هذي الرساله.\n\nطريقة الشرح : طبعا الدكتور ما يستخدم البلاكبورد، بل يستخدم التيمز. وأيضاً ما يستخدم السبوره بل يستخدم الون نوت. طبعا السلاديات تكون في الون نوت و وقت الكلاس يكتب على السلاديات ويشرح عليها، تقدر تشوف اش الدكتور كتب وايش المثال الا حله اليوم عن طريق الون نوت (وهذي ميزه جداً ممتازه عند الدكتور زمو). طبعا الدكتور شرحه رهيب وبداء معك بتدريج الى ان تفهم الفكره.\n\nالكويزات : سهله الى متوسطه (نسخ لصق كويزات الاترام الماضيه مع شويه تغيرات)\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+++++\nالصوت: واضح\nإضافات :\n- الدكتور ما يحب انك تستخدم الجوال وقت المحاضره نهائيا.\n- ما يعطي وجبات\n- الدكتور حبيب واخلقه كويسه لكن لو تستخدم الجوال راح يزعل مره فأنتبه.\n- في التصحيح في المياجر والكويزات الدكتور كان يمشي بعض الاغلاط في حلي او ينقص عليها درجه بسيطه.\n- وأخيرا، نزل عند الدكتور وانت مغمض، الدكتور جدا جدا ممتاز.\n\nلا تنسوني من دعائكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536705-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-zummo-salam-adel/115363/3", "user": "user11794", "ts": 1684791835000, "tid": 115363, "pn": 3}}]}', 1684791835000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5825-ee370', 'stk-user5825', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f118662", "n": "Dr. Zaib Alam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 - lab\n\nشرح ممتاز وواضح للاكسبرمنت ومرة متساعد مع الطلاب اذا ما فهموا حاجة\n\nالكوزات أعطانا 3 كويزات وأخذ أعلى 2\n\nالفاينال لاب كان اختيارات وفراغات وكان متوسط الصعوبة\n\nفي نهاية السمستر قلنا انه راح يحول ينوع في الرينج حق الطلاب فمثلا طالب جاب درجات عالية راح يزيده في الدرجة النهائية أكثر من الطلاب اللي درجاتهم نازلة لأن الافرج كان تحت 15\nبمعنى ان اللي يشتغل تمام في اللاب راح يطلع بدرجة حلوة واللي يهمل فيه ممكن يطلع بدرجة سيئة\n\nالاكسبرمنت اللي يخلص منها يقدر يمشي مو لازم نستنى ينتهي اللاب\n\nالتقييم النهائي: أنصح فيه بشده A+ 🤴", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316360-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-zaib-alam/118662/12", "user": "user5825", "ts": 1389047021000, "tid": 118662, "pn": 12}}]}', 1389047021000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-euler-ee370', 'stk-euler', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f152988", "n": "Dr. Sameh Sorur", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370-131\n\nبنود التقييم :\nالتحضير :\nأول أسبوعين ماكان يحضر , بس بعدها صار يحضر بورقة , تكتب اسمك وال ID , ومايقول شي ع التأخير\n\nطريقة الشرح :\nيكتب ع السبورة أكثر شي , أو يشرح من النوت ع البروجكتور , بعض الأحيان يسوي ريفيو لمسائل الكتاب\n\nالكويزات :\nسهلة وممكن تجي من الهومووركات , أفرج الكويزز نهاية الترم طلع 85.6 %\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالصوت:\nالمدرس لغته قوية وسريع بالكلام , كنت أعاني من هالشيء , يعني أغلب الأحيان ما أفهم عليه , ممكن أكثر الطلاب مايعاني من هالناحية 🌺\n\nإضافات :\nالسمستر هذا أول سمستر له في الجامعة + كان يأخذ من 5 إلى 7 دقايق إضافية ع وقت الكلاص +\nأخلاق وطيب وحريص على فهم الطالب , أيضا متعاون بشكل كبير في الاوفيس 👍\n\nكان أفرج الكورس وتوزيع القريدات ع النحو التالي :\n\nCourse Average : 70.81 % ( set to C+ )o\n\n87.00o to 100.00 A+o\n\n83.00o to 86.99 A\n\no78.00 to 82.99 B+o\n\n74.00o to 77.99 B\n\n68.00o to 73.99 C+o\n\n60.00o to 67.99 C\n\n52.00o to 59.99 D+o\n\n45.00o to 51.99 D\n\n00.00o to 44.99 F\n\nينصح به , بالتوفيق , 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318966-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sameh-sorur/152988/2", "user": "Euler", "ts": 1389667990000, "tid": 152988, "pn": 2}}]}', 1389667990000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ee370', 'stk-abo-da7m', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f152994", "n": "Dr. Hamood Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده لاب ee370 فصل 152\n\nالتحضير :\n\nيمر باللابتوب ويسجل اسمك، متساهل بالتأخير\n\nطريقة الشرح :\n\nيتكلم ويكتب على السبورة، بطول بالشرح شوي ويسهب ويسترتسل بعض الأحيان ويضيع وين كان 🙂\n\nالكويزات :\n\nعطانا 3 كويزات مدري 4 ، كانن متوسطات\n\nالمياجر:\n\nما فيه\n\nالفاينلات :\n\nعطانا فاينل لاب طوييل وكله كتابة ما فيه تجارب. الفانيل كان متوسط وإذا كنت مركز باللاب بتحل معظمه بسهولة\n\nالقريد النهائي:\n\nِa إلى a+\n\nالصوت:\n\nوواضح\n\nإضافات :\n\n- أول لاب حسيت أنهه غثيييث ومتشدد وراعي استقعاد، ثاني وثالث لاب اكتشفت كم هو حبوب و شخصيته رهيييبة.\n\n- من أروع الشخصيات اللي مروا علي، يخليك تبتسم وتضحك غصب.\n\n- يطلب بريبورتات اللاب صور وبوست لاب وورقة اللاب، ما يطلب تعليقات وكنكلوجن\n\n- تصحيحه متوسط لأقشر أحيان بسس هذا زين لأنه يرفع الكل بالنهاية موب زي اللي يوزع درجات ويخسف بالكل آخر شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449780-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hamood-khan/152994/6", "user": "abo-da7m", "ts": 1463735250000, "tid": 152994, "pn": 6}}]}', 1463735250000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9551-ee370', 'stk-user9551', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f153259", "n": "Dr. Suhail Al-Dharrab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE370 term 132\n\nالتحضير :\n\nيحضر بداية كل كلاس و في الاخير يسال عن المتاخرين و يحضرهم\n\nطريقة الشرح :\n\nكان يشرح لنا من سلايدات وجيه ابو السعود و مقيبل … و كانت كافيه جدا لتغطية المنهج مع شرحه\n\nالكويزات :\n\nاعطانا 6 كوزات و ألغى اسوأ واحد … كوزاته من متوسطة الى صعبة\nو فيه نقطة سلبية في بداية الترم و لكن تفاداها في نهاية الترم\nاللي هي اعطاء الحرية الكاملة للقريدر في تصحيح الكوزات ، يقول اللي يعطيك القريدر تأخذه\nلكن في اخر اسبوع قال اللي عنده اعتراض على درجة كوز او هوموورك يجي المكتب\nو اعدلها له اذا كانت الدرجة غير مستحقة\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nA\n\nالصوت:\n\nواضح و الاكسنت مميزة\n\nإضافات :\n\nالدكتور متفاني و مجتهد في عمله … و متعاون جدا مع الطلاب\nيكتب على السبورة و يشرح … و يعيد لو ما انت فاهم … و صدره وسيع مع اسئلة الطلاب\nو يتجاوب مع ايميلات الطلاب >>> غثّ الدكتور بكثرة الايميلات 😆\n\nلكن كلاس ساعة و ربع … جدا ممل سواء مع الدكتور سهيل او غيره\nيعني بعد مرور 50 دقيقة من الكلاس تشوف الطلاب يتململون و يطلعون جوالاتهم\nو هذا شيء طبيعي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1369628-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-suhail-al-dharrab/153259/7", "user": "user9551", "ts": 1400829814000, "tid": 153259, "pn": 7}}]}', 1400829814000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-ee370', 'stk-hammmod', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f153259", "n": "Dr. Suhail Al-Dharrab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nEE 370 Term 161\n\nالتحضير : يوميا أول الكلاس بالإسم اللي يجي متأخر دقيقة يفوته التحضير.\nطريقة الشرح : مملة شوي مدري ليه، الدكتور تحسه موب فاهم مرة ويرتبك إذا أحد سأله، كأنه أول مرة يدرس. طبعا ملخبط الشرح أعجز أكتب معه. يستخدم البروجكتور دايم يعرض فيه رسمات أو أي توضيحات. طبعا يعتمد على نوتات وجيه أبو السعود وما يرفعها الا بعد الكلاس.\nالكويزات : صعبة شوي وتاخذ وقت. لازم تستعد لها بشكل جيد.\nالمياجر: متوسطة\nالفاينلات :-\nالقريد النهائي: C+\nالصوت: واضح وآكسنت جيدة\nإضافات : الدكتور طيب وأخلاقه عسل ومرن ومحترم ويعيد ويزيد في الشرح، بس مدري ما يزال فيه شوي فجوة A guy who lacks attitude. أيضا كلاسه كان طوييييييل وقليلين اللي مركزين معه. لكن يرحب فيك في الأوفيس ولو ترسل له ايميل يتفاعل معك\n\nلو يخلي لنا مثلا مجال نحل أمثله بأنفسنا أثناء الكلاس عشان ندخل معه يكون أفضل.\n\nلو لقيت غيره أفضل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465062-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-suhail-al-dharrab/153259/8", "user": "hAmMmOd", "ts": 1482415030000, "tid": 153259, "pn": 8}}]}', 1482415030000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahad_ahmad878-ee370', 'stk-fahad_ahmad878', 'EE 370', 'doc', '{"docs": [{"id": "stk-dr-f176830", "n": "Dr. Ali Arshad Nasir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 182 EE 370\n\nبنود التقييم :\n\nالتحضير :\nبداية كل محاضرة ويكون على البلاكبورد ، مافيه كلاس ما حضر حتى الإسبوع 15 آخر يوم حضر ، حذف 3 غيابات لكل واحد .\n\nطريقة الشرح :\nكان يستعمل فقط السبورة في الشرح وقليل ما يستعمل السلايدات(اذا كان فيه رسمات توضيحية فقط) .\nالدكتور كان ايصالة للمعلومة جدا سيء من يوم يدخل إلى ماتخلص المحاضرة و هو يشرح بشكل عشوائي لدرجة إنك ماتدري وش الفكرة اللي يبي يوصلها لك .\nكان كثير متردد بالشرح و بعض الأحيان يسئلونه الطلاب عن بعض الجزئيات لكن مايعرفها ويقول أعلمكم الكلاس الجاي و كان بالغالب يسحب .\nإذا سئلته عن معلومه مافهمتها بيضل يعيدها لك بنفس إسلوب الشرح.\n\nالكويزات :\nكانت 5 كوزات + 1 بونص\nأول 3 كوزات كانت صعبة مره و أفكارها غريبة ماهي موجودة بالهوموركات و لا الأولد إقزام و تصحيحة كان يا صفريا فل .\nآخر 3 كوزات كانت سهلة و واضحة إذا مذاكر ويتساعد بالتصحيح .\n\nالمياجر:\nالمياجر كانت كومون و التصحيح بالملي يمشي على Answer Key , كان يخلص تصحيح المياجر بسرعة (أول كلاس بعد الميجر يوزع الأوراق) و كان كثير يخطي بحساب الدرجات(حصلت لي و لأكثر من واحد بالكلاس) .\nمهم تراجعه بعد الميجر لأنه مع الإستعجال بالتصحيح مايحسب لك بعض الحاجات.\n\nالفاينلات :\nكان كومن و شامل لكل المنهج\n\nالصوت:\nواضح ومسموع للجميع .\n\nإضافات :\n1-الدكتور حبيب و أخلاقة تمام .\n2-طريقة إيصالة للمعلومة كان جدا سيئة.\n3-يعطيك حقك بالملي ولا يدف أحد.\n4-دايم نطلب منه تأجيل الهومورك ولا يأجله إلا إذا كان الدكتور الثاني أجله لطلابة.\n5-الهوموركات مايدقق بتصحيحها وكان بالغالب يعطيك فل إذا حليت كل الأسئلة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510044-ee370", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-arshad-nasir/176830/5", "user": "Fahad_ahmad878", "ts": 1558522073000, "tid": 176830, "pn": 5}}]}', 1558522073000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
